import { InvoiceLineItems } from '../../invoice/entities/invoice.entity.js';
import { Offering } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    overageAllowedEnum,
    roundingEnum,
} from '../../dimensions/dto/create-dimension.dto.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';

const baseDimension = (overrides) => ({
    dimensionId: 'dim',
    dimensionName: 'Dim',
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.sum,
    usageIncrement: '1',
    rounding: roundingEnum.round,
    consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
    ...overrides,
});

const run = async (dimension, usageValue: string, settings: ReadSettingsResponseData, negative = false) => {
    const offeringConfig = {
        offeringId: 'off',
        offeringName: 'Off',
        offeringType: OfferingType.usageBased,
        currency: SupportedCurrencies.USD,
        billingCycle: ValidBillingCycles.monthly,
        dimensions: [dimension],
    };
    const usageOverrides =
        usageValue === undefined
            ? []
            : [
                  {
                      dimensionId: dimension.dimensionId,
                      usage: [{ value: usageValue, startTime: '2026-07-01T00:00:00Z', endTime: '2026-07-02T00:00:00Z' }],
                  },
              ];
    const instance = Offering.getInstance(
        offeringConfig as never,
        'cus',
        'biz',
        undefined,
        settings,
        undefined,
        undefined,
        undefined,
        usageOverrides as never,
    );
    const lineItems = await Offering.getLineItemsForUsage({
        startDate: new Date('2026-07-01T00:00:00Z'),
        endDate: new Date('2026-08-01T00:00:00Z'),
        lineItems: new InvoiceLineItems(),
        businessID: 'biz',
        customerId: 'cus',
        customerService: undefined,
        dimensions: offeringConfig.dimensions as never,
        offeringInstance: instance,
        negative,
    });
    return lineItems.getLineItems().map(({ name, quantity, unitCost }) => ({ name, quantity, unitCost }));
};

const show = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData;
const hide = { freeDimensionOnInvoice: FreeDimensionOnInvoice.hide } as ReadSettingsResponseData;

describe('allowance and free dimension rules', () => {
    test('no allowance charges all usage', async () => {
        expect(await run(baseDimension({ consumptionPrice: '2' }), '10', show)).toEqual([
            { name: 'Dim - Off', quantity: 10, unitCost: 2 },
        ]);
    });
    test('exhausted finite allowance with overage charges the excess only', async () => {
        expect(
            await run(
                baseDimension({ consumptionPrice: '2', usageEntitlement: 4, overageAllowed: overageAllowedEnum.true }),
                '10',
                show,
            ),
        ).toEqual([{ name: 'Dim - Off', quantity: 6, unitCost: 2 }]);
    });
    test('allowance expressed as a string still applies', async () => {
        expect(
            await run(
                baseDimension({ consumptionPrice: '2', usageEntitlement: '4', overageAllowed: 'true' }),
                '10',
                show,
            ),
        ).toEqual([{ name: 'Dim - Off', quantity: 6, unitCost: 2 }]);
    });
    test('usage exactly at the allowance charges nothing and gets no line', async () => {
        expect(
            await run(
                baseDimension({ consumptionPrice: '2', usageEntitlement: 10, overageAllowed: overageAllowedEnum.true }),
                '10',
                show,
            ),
        ).toEqual([]);
    });
    test('unlimited allowance charges nothing', async () => {
        expect(
            await run(
                baseDimension({
                    consumptionPrice: '2',
                    usageEntitlement: 'inf',
                    overageAllowed: overageAllowedEnum.true,
                }),
                '10',
                show,
            ),
        ).toEqual([]);
    });
    test('overage forbidden charges nothing', async () => {
        expect(
            await run(
                baseDimension({ consumptionPrice: '2', usageEntitlement: 4, overageAllowed: overageAllowedEnum.false }),
                '10',
                show,
            ),
        ).toEqual([]);
    });
    test('overage unspecified charges nothing', async () => {
        expect(await run(baseDimension({ consumptionPrice: '2', usageEntitlement: 4 }), '10', show)).toEqual([]);
    });
    test('zero priced dimension is listed when free dimensions are shown', async () => {
        expect(await run(baseDimension({ consumptionPrice: '0' }), '10', show)).toEqual([
            { name: 'Dim - Off', quantity: 10, unitCost: 0 },
        ]);
    });
    test('zero priced dimension is omitted when free dimensions are hidden', async () => {
        expect(await run(baseDimension({ consumptionPrice: '0' }), '10', hide)).toEqual([]);
    });
    test('zero priced dimension without usage is still listed when shown', async () => {
        expect(await run(baseDimension({ consumptionPrice: '0' }), undefined, show)).toEqual([
            { name: 'Dim - Off', quantity: 0, unitCost: 0 },
        ]);
    });
    test('priced dimension without usage gets no line', async () => {
        expect(await run(baseDimension({ consumptionPrice: '2' }), undefined, show)).toEqual([]);
    });
    test('missing settings default to showing free dimensions', async () => {
        expect(await run(baseDimension({ consumptionPrice: '0' }), '3', undefined)).toEqual([
            { name: 'Dim - Off', quantity: 3, unitCost: 0 },
        ]);
    });
    test('usage increment applies to the chargeable overage', async () => {
        expect(
            await run(
                baseDimension({
                    consumptionPrice: '2',
                    usageIncrement: '10',
                    usageEntitlement: 100,
                    overageAllowed: overageAllowedEnum.true,
                }),
                '150',
                show,
            ),
        ).toEqual([{ name: 'Dim - Off', quantity: 5, unitCost: 2 }]);
    });
    test('free trial credits negate only the chargeable overage', async () => {
        expect(
            await run(
                baseDimension({ consumptionPrice: '2', usageEntitlement: 4, overageAllowed: overageAllowedEnum.true }),
                '10',
                show,
                true,
            ),
        ).toEqual([{ name: 'Dim - Off - Free Trial Credit', quantity: -6, unitCost: 2 }]);
    });
    test('dimension with an allowance and no price yields no line', async () => {
        expect(await run(baseDimension({ usageEntitlement: 4 }), '10', show)).toEqual([]);
    });
});
