    /**
     * What a dimension's readings add up to over the invoiced period, carried to
     * the two decimal places an invoice is denominated in.
     */
    static billableTotal(usage: AggregatedUsageResponse['usage']): string {
        const total = (usage ?? []).reduce((acc, { value }) => {
            acc += parseFloat(value);
            return acc;
        }, 0);
        return total.toFixed(2).toString();
    }

    /**
     * The portion of a dimension's usage the customer can actually be charged
     * for, once the allowance the plan grants them has been taken into account.
     *
     * A dimension without an allowance is billed on all of its usage. An
     * allowance of `inf` is never exhausted, so nothing is billable. A finite
     * allowance only ever yields the usage above it, and only when the plan
     * permits overage: if overage is not allowed the allowance acts as a cap
     * and nothing is billable.
     */
    static chargeableUsage({ dimension, total }: { dimension: ReadDimensionResponseData; total: number }): number {
        const usageTotal = Number(total);
        const entitlement = dimension?.usageEntitlement;
        if (entitlement === undefined || entitlement === null) {
            // No allowance is granted, every unit of usage is chargeable.
            return Number.isFinite(usageTotal) ? usageTotal : 0;
        }
        if (entitlement === 'inf') {
            // An unlimited allowance can never be exhausted.
            return 0;
        }
        const overageAllowed = dimension?.overageAllowed as unknown;
        if (overageAllowed !== overageAllowedEnum.true && overageAllowed !== true) {
            // The plan forbids overage, so the allowance is a hard cap.
            return 0;
        }
        const entitlementAmount = parseFloat(entitlement as unknown as string);
        if (!Number.isFinite(entitlementAmount)) {
            return Number.isFinite(usageTotal) ? usageTotal : 0;
        }
        const overage = usageTotal - entitlementAmount;
        return overage > 0 ? overage : 0;
    }

    /**
     * Whether a dimension deserves a line on the invoice. Anything the customer
     * owes money for is always listed. A dimension the plan prices at zero owes
     * nothing but is still listed, unless the business has asked for free
     * dimensions to be kept off of their invoices.
     */
    static shouldAddUsageLineItem({
        chargeableTotal,
        unitCost,
        settings,
    }: {
        chargeableTotal: number;
        unitCost: number;
        settings?: ReadSettingsResponseData;
    }): boolean {
        if (unitCost === 0) {
            return settings?.freeDimensionOnInvoice !== FreeDimensionOnInvoice.hide;
        }
        return Number.isFinite(chargeableTotal) && chargeableTotal > 0 && Number.isFinite(unitCost);
